#!/bin/sh
# The drift test of the grammars, the drop-in directory spec/grammars.d/ (errata 180) and the masters spec/pdp64/pdp64.hbnf (the encoding) and spec/pdp64-asm.hbnf (the assembly
# language), the source of truth of the encoding and the syntax.
#
#   0. the rules of the directory (tools/grammars_d.py --check): every part is named NN-name.hbnf, a number is used once, each part has its `; targets:` line, no rule is defined
#      twice (the message names both files), a generated part begins `; GENERATED by ...` and a hand-written one does not, the masters hold directives only and include the
#      generated indexes, and the generated parts and indexes (`insn`, `mnemonic`, the include lists) are what tools/grammars_d.py writes from the directory as it is: a part
#      added, removed or renamed without `python3 tools/grammars_d.py --write` is a stale index and fails here;
#   1. hbnf accepts both grammars (the syntax, the references, the widths) and generates a decoder (parse_bits) and the assembly parser from them;
#   2. the parts of tools/encopt/addforms.py are written again, into a scratch directory (no --drop, from the committed grammar and vecfam.py): each must be byte for byte the
#      committed part; a difference means vecfam.py changed (run the generator workflow of spec/README.md, ending with `tools/encopt/addforms.py --grammar-out DIR` and a copy into
#      spec/grammars.d/) or a generated part was edited by hand.  Then everything else is generated again from the grammar, into the scratch directory: a checked-in generated file
#      that differs (spec/pdp64/tables.md) fails, and so does a generated table that is not the one recorded in tests/enc/generated.sha256 (the C tables of the codec, the field
#      accessors, the name tables of as64).  After a deliberate change of a grammar: tools/check-grammar-enc.sh --update, and review the diff;
#   3. hbnf's decoder against the codec built from the generated tables, on every first parcel and four tails each: the same legal and illegal patterns, the
#      same length, the same leaf, the same raw value in every field (tests/enc/hbdec.c).
#
# HBNF and HBNF_TEMPLATES as in tools/build-as64.sh.
set -e
cd "$(dirname "$0")/.."
HBNF=${HBNF:-/tmp/hbnf-latest/hbnf}
TPL=${HBNF_TEMPLATES:-/tmp/hbnf-latest/hbnf-templates}
T=$(mktemp -d "${TMPDIR:-/tmp}/grammar-enc.XXXXXX")
trap 'rm -rf "$T"' EXIT
GOLD=tests/enc/generated.sha256
FILES="pdp64-tab.c pdp64-hbfields.h x/pdp64-groups.h x/pdp64-extnames.h x/pdp64-mnnames.h"
export BUILD=$T
GEN=spec/grammars.d
python3 tools/mkparts.py --check || exit 1
python3 tools/grammars_d.py --check || exit 1
python3 tools/encopt/addforms.py --grammar-out "$T/af" > "$T/af.log" || { cat "$T/af.log"; exit 1; }
for f in "$T"/af/*.hbnf; do
	if ! cmp -s "$f" "$GEN/$(basename "$f")"; then
		diff "$f" "$GEN/$(basename "$f")" | head -40
		echo "check-grammar-enc: tools/encopt/addforms.py does not write $GEN/$(basename "$f") (vecfam.py changed without the generator workflow, or a generated part was edited by hand)"
		exit 1
	fi
done
for f in "$GEN"/*.hbnf; do
	if head -n 1 "$f" | grep -q '^; GENERATED by tools/encopt/addforms.py'; then
		[ -f "$T/af/$(basename "$f")" ] || { echo "check-grammar-enc: $f is not written by tools/encopt/addforms.py (a stale generated part: delete it)"; exit 1; }
	fi
done
python3 tools/mkgrammar.py
python3 tools/mkenc.py --check
sum=$(cd "$T" && sha256sum $FILES)
if [ "$1" = "--update" ]; then
	printf '%s\n' "$sum" > "$GOLD"
	echo "check-grammar-enc: $GOLD rewritten"
	exit 0
fi
if ! printf '%s\n' "$sum" | diff - "$GOLD" > "$T/diff"; then
	cat "$T/diff"
	echo "check-grammar-enc: the generated files are not the ones recorded in $GOLD (a grammar changed? run tools/check-grammar-enc.sh --update and review)"
	exit 1
fi
"$HBNF" spec/pdp64-asm.hbnf --backend=c --templates="$TPL" --ast --spans --no-compact --no-overlay > "$T/pdp64-asm-parser.c"
"$HBNF" spec/pdp64/pdp64.hbnf --backend=c --templates="$TPL" > "$T/pdp64-hbdec.c"
gcc -O1 -w -DHBDEC="\"pdp64-hbdec.c\"" -DHBFIELDS="\"pdp64-hbfields.h\"" -I"$T" -Icommon -o "$T/hbdec" tests/enc/hbdec.c common/pdp64enc.c "$T/pdp64-tab.c"
"$T/hbdec"
echo "check-grammar-enc: ok"
